// ariel: terminal emulation (xterm-256color class) in C11, no allocation
//
// $ cc -std=c11 -c -O2 ariel.c
//
// The whole terminal lives in one caller block: a fixed header (struct
// ariel_Term) followed by areas reached through u32 offsets from the
// block's start, so the block can be copied or moved as plain bytes. The
// areas: three grids (main, alternate, a spare for reflow), each cells,
// row heads and a row map; a cluster pool; and history. A grid's rows
// sit at a stride of capcols cells, and the map turns a screen row into
// a slot, so scrolling rotates the map rather than moving cells.
//
// Parsing follows the vt100.net (Williams) state machine, UTF-8 only.
// Events, including replies, leave through ariel_feed's return value.
//
// This is free and unencumbered software released into the public domain.
