// Control

// Shrink one screen to rows, keeping its cursor row (y) in view: blank
// rows below the cursor go first, then rows leave the top for history.
static void resizerows(ariel_Term *t, i32 scr, i32 rows, i32 *y)
{
    i32 drop = t->rows - rows;
    if (drop <= 0) return;
    i32 save = t->scr;
    t->scr = scr;
    i32 r = t->rows - 1;
    for (; drop>0 && r>*y && rowblank(t, r); r--, drop--) {}
    if (drop > 0) {
        scrollup(t, 0, t->rows-1, drop, 1);
        *y = imax(*y - drop, 0);
    }
    t->scr = save;
}

int32_t ariel_resize(ariel_Term *t, int32_t cols, int32_t rows, int32_t cellw, int32_t cellh)
{
    affirm(t->magic == MAGIC);
    if (cols<2 || rows<1 || cols>t->capcols || rows>t->caprows) {
        return 0;
    }
    t->cellw = imax(cellw, 0);
    t->cellh = imax(cellh, 0);
    if (cols==t->cols && rows==t->rows) {
        return 1;
    }

    i32 oldcols = t->cols, oldrows = t->rows;
    b32 stepright = t->c.wrapnext && cols>oldcols;
    i32 y = t->c.y;
    resizerows(t, t->scr, rows, &y);
    t->c.y = y;
    i32 other = t->saved[!t->scr].y;
    resizerows(t, !t->scr, rows, &other);
    t->saved[!t->scr].y = other;

    Cell b = {0};
    t->cols = cols;
    t->rows = rows;
    for (i32 g = 0; g < 2; g++) {
        Cell *cells = gridcells(t, g);
        u16  *map   = gridmap(t, g);
        for (i32 r = 0; r < rows; r++) {
            if (r >= oldrows) {
                clearslot(t, g, map[r], b);
                continue;
            }
            Cell *c = cells + (iz)map[r]*t->capcols;
            if (cols > oldcols) {
                fillcells(c+oldcols, cols-oldcols, b);
            } else if (cellkind(c+cols-1) == KIND_WIDE) {
                c[cols-1].cp  = 0;
                c[cols-1].ext = 0;
            }
            gridheads(t, g)[map[r]].gen = t->gen + 1;
        }
    }
    if (cols > oldcols) {
        tabsreset(t, oldcols);
    }

    t->top = 0;
    t->bot = rows - 1;
    t->c.x = imin(t->c.x + stepright, cols-1);
    t->c.y = imin(t->c.y, rows-1);
    t->c.wrapnext = 0;
    for (i32 s = 0; s < 2; s++) {
        t->saved[s].x = imin(t->saved[s].x, cols-1);
        t->saved[s].y = imin(t->saved[s].y, rows-1);
    }
    segclear(t);
    t->dirty = 1;
    return 1;
}

void ariel_setcolor(ariel_Term *t, int32_t index, uint32_t rgb)
{
    affirm(t->magic == MAGIC);
    if (index<0 || index>=ARIEL_C_COUNT) return;
    t->paldef[index] = rgb & 0xffffff;
    t->pal[index]    = rgb & 0xffffff;
    touchall(t);
}

uint32_t ariel_color(ariel_Term *t, int32_t index)
{
    affirm(t->magic == MAGIC);
    return index>=0 && index<ARIEL_C_COUNT ? t->pal[index] : 0;
}

void ariel_setflags(ariel_Term *t, uint32_t flags)
{
    affirm(t->magic == MAGIC);
    u32 mask = ARIEL_F_WIDEAMBIG | ARIEL_F_BOLDBRIGHT | ARIEL_F_CLIPREAD |
               ARIEL_F_NOREPLY;
    t->flags = (t->flags & ~mask) | (flags & mask);
    touchall(t);
}

void ariel_reset(ariel_Term *t, int32_t what)
{
    affirm(t->magic == MAGIC);
    if (what & ARIEL_RESET_FULL) {
        ris(t);
        return;
    }
    if (what & ARIEL_RESET_HISTORY) {
        clearhistory(t);
    }
    if (what & ARIEL_RESET_SCREEN) {
        clearscreen(t);
        setcursor(t, 0, 0);
    }
}

ptrdiff_t ariel_export(ariel_Term *t, int32_t histlines, uint8_t *out, ptrdiff_t cap)
{
    affirm(t->magic == MAGIC);
    (void)histlines;
    (void)out;
    (void)cap;
    return 0;   // L3
}

// Like Out, but counts what doesn't fit
typedef struct {
    u8 *buf;
    iz  len, cap;
} Dump;

static void dumpbytes(Dump *d, ariel_Str s)
{
    iz n = s.len;
    if (d->len < d->cap) {
        iz room = d->cap - d->len;
        xcpy(d->buf+d->len, s.data, n<room ? n : room);
    }
    d->len += n;
}

static void dumpout(Dump *d, Out *o)
{
    ariel_Str s = {o->buf, o->len};
    dumpbytes(d, s);
}

ptrdiff_t ariel_dump(ariel_Term *t, int32_t flags, uint8_t *out, ptrdiff_t cap)
{
    affirm(t->magic == MAGIC);
    Dump d = {out, 0, cap};
    u8   buf[256];
    if (flags & ARIEL_DUMP_STATE) {
        Out o = newout(buf, countof(buf));
        outs(&o, S("size "));
        outi(&o, t->cols);
        outc(&o, 'x');
        outi(&o, t->rows);
        outs(&o, S(" cursor "));
        outi(&o, t->c.y);
        outc(&o, ',');
        outi(&o, t->c.x);
        if (t->c.wrapnext) outs(&o, S(" wrapnext"));
        if (t->scr) outs(&o, S(" alt"));
        outc(&o, '\n');
        dumpout(&d, &o);
    }
    for (i32 y = 0; y < t->rows; y++) {
        Cell *r = row(t, y);
        i32 end = t->cols;
        for (; end>0 && !cellcp(r+end-1); end--) {}
        for (i32 x = 0; x < end; x++) {
            Out o = newout(buf, countof(buf));
            i32 kind = cellkind(r+x);
            if (kind == KIND_TAIL) continue;
            u32 cp = cellcp(r+x);
            oututf8(&o, cp && kind!=KIND_SPACER ? cp : ' ');
            u32 extra[POOLN];
            i32 n = cellextra(t, r+x, extra, POOLN);
            for (i32 i = 0; i < imin(n, POOLN); i++) {
                oututf8(&o, extra[i]);
            }
            dumpout(&d, &o);
        }
        dumpbytes(&d, S("\n"));
        if (!(flags & ARIEL_DUMP_ATTRS)) continue;
        for (i32 x = 0; x < t->cols;) {
            Cell *c = r + x;
            i32   e = x + 1;
            for (; e<t->cols && r[e].fg==c->fg && r[e].bg==c->bg &&
                   r[e].ul==c->ul && r[e].attr==c->attr; e++) {}
            if (c->fg || c->bg || c->ul || c->attr) {
                Out o = newout(buf, countof(buf));
                outc(&o, '\t');    // never in a row's text
                outi(&o, x);
                outc(&o, '-');
                outi(&o, e-1);
                Pen p = {c->fg, c->bg, c->ul, c->attr, 0};
                outs(&o, S(" sgr "));
                outsgr(&o, &p);
                outc(&o, '\n');
                dumpout(&d, &o);
            }
            x = e;
        }
    }
    return d.len;
}
